import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import {
  uv, vec3, vec4, mix, smoothstep, uniform, positionLocal, color, float, step, abs, sub
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, BoxGeometry, PlaneGeometry, DirectionalLight, AmbientLight, Color } = ctx.THREE;

  const spec = config.intent?.visualSpec ?? {};
  const colors = spec.colors ?? config.colors ?? {};
  const C = {
    background: colors.background ?? '#0b0b10',
    surface: colors.surface ?? '#14141a',
    paper: colors.paper ?? '#e8ecf2',
    accent: colors.accent ?? '#ff2a38',
    gs0: colors.gradientStops?.[0]?.hex ?? '#101017',
    gs1: colors.gradientStops?.[1]?.hex ?? '#1a1a22'
  };

  const items = config.textContent ?? spec.textContent ?? [];
  const getByRole = (role, idx) => {
    const matches = items.filter((i) => i.role === role);
    return matches[idx];
  };
  const textOf = (item, fallback) => (item && typeof item.text === 'string' ? item.text : fallback);

  const root = new Group();
  root.userData.handlers = {};
  const timelines = [];
  const disposables = [];

  // ---- Lighting (node-local rim/accent) ----
  const ambient = new AmbientLight(new Color(C.paper), 0.35);
  const key = new DirectionalLight(new Color('#ffffff'), 1.1);
  key.position.set(-3, 4, 5);
  const rim = new DirectionalLight(new Color(C.accent), 0.7);
  rim.position.set(4, -2, 3);
  root.add(ambient, key, rim);

  // ---- Backdrop stage plane with vertical gradient ----
  const backGeo = new PlaneGeometry(7, 6);
  const backMat = new MeshBasicNodeMaterial();
  {
    const g0 = color(new Color(C.gs0));
    const g1 = color(new Color(C.gs1));
    const t = uv().y;
    backMat.colorNode = mix(g0, g1, smoothstep(0.0, 1.0, t));
  }
  const backdrop = new Mesh(backGeo, backMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  disposables.push(backGeo, backMat);

  // ---- Machined slab material factory (engineered diagonal gradient + sheen band) ----
  function makeSlabMaterial() {
    const mat = new MeshStandardNodeMaterial();
    mat.roughness = 0.55;
    mat.metalness = 0.45;
    mat.clearcoat = 0.2;

    const g0 = color(new Color(C.gs0));
    const g1 = color(new Color(C.gs1));
    // 135-deg diagonal coordinate
    const p = uv();
    const diag = p.x.add(sub(float(1.0), p.y)).mul(0.5); // 0..1 along 135deg
    let base = mix(g0, g1, smoothstep(0.0, 1.0, diag));
    // hard-stop sheen band ~0.15 wide at 40%, +6% value
    const bandCenter = float(0.4);
    const bandHalf = float(0.075);
    const band = step(abs(diag.sub(bandCenter)), bandHalf);
    const sheen = base.add(vec3(0.06, 0.06, 0.06)).mul(band);
    mat.colorNode = mix(base, sheen, band);
    return mat;
  }

  // ---- Cell builder ----
  const grid = new Group();
  root.add(grid);

  const cells = [];
  function buildCell(w, h, cx, cy) {
    const cell = new Group();
    cell.position.set(cx, cy, 0);

    const geo = new BoxGeometry(w, h, 0.06);
    const mat = makeSlabMaterial();
    const slab = new Mesh(geo, mat);
    cell.add(slab);
    disposables.push(geo, mat);

    // accent tick bar top-left inside padding
    const tickGeo = new PlaneGeometry(0.4, 0.05);
    const tickMat = new MeshStandardNodeMaterial();
    tickMat.colorNode = color(new Color(C.accent));
    tickMat.emissiveNode = color(new Color(C.accent)).mul(float(1.3));
    tickMat.roughness = 0.6;
    const tick = new Mesh(tickGeo, tickMat);
    tick.position.set(-w / 2 + 0.5 + 0.2, h / 2 - 0.5 + 0.0, 0.04);
    cell.add(tick);
    disposables.push(tickGeo, tickMat);

    grid.add(cell);
    cells.push({ group: cell, w, h });
    return { cell, w, h };
  }

  // Grid: 5.5 x 3.5, gutter 0.25
  // Dominant left 3.25 x 3.5; right column two cells 2.0 x 1.625 stacked
  const dominantW = 3.25, dominantH = 3.5;
  const secW = 2.0, secH = 1.625;

  // Left column center x
  const domX = -2.75 + dominantW / 2; // = -1.125
  const rightX = 2.75 - secW / 2; // = 1.75
  const secTopY = 3.5 / 2 - secH / 2; // 0.9375
  const secBotY = -(3.5 / 2 - secH / 2);

  const dom = buildCell(dominantW, dominantH, domX, 0);
  const secTop = buildCell(secW, secH, rightX, secTopY);
  const secBot = buildCell(secW, secH, rightX, secBotY);

  // ---- Text ----
  function addText(parent, content, opts, x, y) {
    const t = ctx.fontAtlas.createText(content, opts);
    t.position.set(x, y, 0.05);
    parent.add(t);
    return t;
  }

  // Header caption above grid, left-aligned to grid edge
  const capItem = getByRole('caption', 0);
  addText(
    root,
    textOf(capItem, 'ATELIER METRICS / Q2 2026'),
    { fontSize: 18, color: C.accent, align: 'left', letterSpacingPx: 2.2 },
    -2.75,
    3.5 / 2 + 0.5
  );

  // Dominant cell: valueLarge + label
  const domVal = getByRole('valueLarge', 0);
  const domLabel = getByRole('label', 0);
  const domPadX = -dominantW / 2 + 0.5;
  addText(
    dom.cell,
    textOf(domVal, '0.002 mm'),
    { fontSize: 124, color: C.paper, align: 'left' },
    domX + domPadX,
    0.25
  );
  addText(
    dom.cell,
    textOf(domLabel, 'Case tolerance, CNC pass'),
    { fontSize: 18, color: C.paper, align: 'left', letterSpacingPx: 1.4 },
    domX + domPadX,
    -0.25
  );

  // Secondary cells: value + label
  const valTop = getByRole('value', 0);
  const labTop = getByRole('label', 1);
  const secPadX = -secW / 2 + 0.5;
  addText(
    secTop.cell,
    textOf(valTop, '38 h'),
    { fontSize: 68, color: C.paper, align: 'left' },
    rightX + secPadX,
    secTopY + 0.15
  );
  addText(
    secTop.cell,
    textOf(labTop, 'Power reserve, NA-01'),
    { fontSize: 18, color: C.paper, align: 'left', letterSpacingPx: 1.4 },
    rightX + secPadX,
    secTopY - 0.35
  );

  const valBot = getByRole('value', 1);
  const labBot = getByRole('label', 2);
  addText(
    secBot.cell,
    textOf(valBot, '214'),
    { fontSize: 68, color: C.paper, align: 'left' },
    rightX + secPadX,
    secBotY + 0.15
  );
  addText(
    secBot.cell,
    textOf(labBot, 'Components per calibre'),
    { fontSize: 18, color: C.paper, align: 'left', letterSpacingPx: 1.4 },
    rightX + secPadX,
    secBotY - 0.35
  );

  // ---- Entrance: stagger-cards fade-up, dominant first ----
  const ordered = [dom.cell, secTop.cell, secBot.cell];
  ordered.forEach((c) => { c.position.y -= 0.2; });
  const introTl = gsap.timeline();
  ordered.forEach((c, i) => {
    const targetY = c.position.y + 0.2;
    introTl.to(c.position, {
      y: targetY,
      duration: 0.5,
      ease: 'power2.out'
    }, i * 0.08);
  });
  timelines.push(introTl);

  // ---- Hover press-down / weighted-settle per cell ----
  root.userData.handlers.hover = (payload) => {
    const target = ordered[0]; // dominant as focus proxy
    gsap.to(target.scale, { x: 0.97, y: 0.97, duration: 0.12, ease: 'back.out(2)' });
  };
  root.userData.handlers.hoverEnd = () => {
    const target = ordered[0];
    const tl = gsap.timeline();
    tl.to(target.scale, { x: 1.04, y: 1.04, duration: 0.0 })
      .to(target.scale, { x: 1.0, y: 1.0, duration: 0.9, ease: 'power4.out' });
    timelines.push(tl);
  };
  root.userData.handlers.click = () => {
    ctx.emit('navigate', { to: 'hub-features' });
  };

  // ---- Idle breathing (single slow transform) ----
  const idleTl = gsap.timeline({ repeat: -1, yoyo: true });
  idleTl.to(grid.scale, { x: 1.008, y: 1.008, duration: 4, ease: 'sine.inOut' });
  timelines.push(idleTl);

  root.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    gsap.killTweensOf(ordered.map((c) => c.scale));
    gsap.killTweensOf(grid.scale);
    disposables.forEach((d) => { try { d.dispose && d.dispose(); } catch (e) {} });
  };

  return root;
}
